#define AUTH_FLOOR 0

	AUTH_PSK,
	AUTH_NULL,

	AUTH_RSASSA_PKCS1_V1_5_SHA1_RAW,

	AUTH_ECDSA_SHA2_256_RAW,
	AUTH_ECDSA_SHA2_384_RAW,
	AUTH_ECDSA_SHA2_512_RAW,

	/*
