static struct authby extract_authby(struct kv kv,
				    enum ike_version ike_version,
				    diag_t *d)
{
	if (*d != NULL) {
		return (struct authby) {0};
	}

	/*
	 * Read in the authby= string and translate to policy bits.
	 *
	 * This is the symmetric (left+right) version.  There is also
	 * leftauth=/rightauth= version stored in 'end'
	 *
	 * authby=secret|psk|rsasig|null|never|rsa-HASH
	 *
	 * using authby=rsasig results in both RSASIG_v1_5 and RSA_PSS
	 *
	 * HASH needs to use full syntax - eg sha2_256 and not sha256,
	 * to avoid confusion with sha3_256
	 */

	struct authby authby = {0};
	shunk_t curseby = shunk1(kv.value);
	while (true) {

		shunk_t val = shunk_token(&curseby, NULL/*delim*/, ", ");
		if (val.ptr == NULL) {
			break;
		}
#if 0
		if (val.len == 0) {
			/* ignore empty fields? */
			continue;
		}
#endif

		/* Supported for IKEv1 and IKEv2 */
		switch (ike_version) {
#ifdef USE_IKEv1
		case IKEv1:
			if (hunk_streq(val, "secret") ||
			    hunk_streq(val, "psk")) {
				authby = authby_or(authby, (struct authby) {
						AUTHBY_PSK,
					});
				continue;
			}
			if (hunk_streq(val, "rsasig") ||
			    hunk_streq(val, "rsa")) {
				authby = authby_or(authby, (struct authby) {
						AUTHBY_RSASIG_IKEv1,
					});
				continue;
			}
			if (hunk_streq(val, "never")) {
				authby = authby_or(authby, (struct authby) {
						AUTHBY_NEVER,
					});
				continue;
			}
			*d = diag("authby="PRI_SHUNK" is not valid for IKEv1",
				  pri_shunk(val));
			return (struct authby) {0};
#endif
		case IKEv2:
		{
			struct authby moreby = {0};
			if (!tto_ikev2_authby(val, &moreby)) {
				*d = diag("authby="PRI_SHUNK" is unknown", pri_shunk(val));
				return (struct authby) {0};
			}
			authby = authby_or(authby, moreby);
			continue;
		}
		}
		bad_case(ike_version);
	}

	return authby;
}

static bool authby_conflicts(struct authby *conflicts,
			     struct authby authby,
			     struct authby expected)
{
	*conflicts = authby_and(authby, authby_not(expected));
	return authby_is_set(*conflicts);
}

