struct v2AUTH_blobs {
	uint32_t mid;
	struct hash_hunk blob[8];
	struct hash_hunks hunks;
};

static const uint8_t v2AUTH_zero_prefix[8] = {0};

/*
 * draft-ietf-ipsecme-ikev2-downgrade-prevention-08, "Authentication
 * in IKEv2":
 * https://www.ietf.org/archive/id/draft-ietf-ipsecme-ikev2-downgrade-prevention-08.html#name-authentication-in-ikev2
 *
 * When the extension has not been negotiated:
 *
 *   InitiatorSignedOctets = RealMessage1 | NonceRData | MACedIDForI
 *   GenIKEHDR = [ four octets 0 if using port 4500 ] | RealIKEHDR
 *   RealIKEHDR =  SPIi | SPIr |  . . . | Length
 *   RealMessage1 = RealIKEHDR | RestOfMessage1
 *   NonceRPayload = PayloadHeader | NonceRData
 *   InitiatorIDPayload = PayloadHeader | RestOfInitIDPayload
 *   RestOfInitIDPayload = IDType | RESERVED | InitIDData
 *   MACedIDForI = prf(SK_pi, RestOfInitIDPayload)
 *
 *   ResponderSignedOctets = RealMessage2 | NonceIData | MACedIDForR
 *   GenIKEHDR = [ four octets 0 if using port 4500 ] | RealIKEHDR
 *   RealIKEHDR =  SPIi | SPIr |  . . . | Length
 *   RealMessage2 = RealIKEHDR | RestOfMessage2
 *   NonceIPayload = PayloadHeader | NonceIData
 *   ResponderIDPayload = PayloadHeader | RestOfRespIDPayload
 *   RestOfRespIDPayload = IDType | RESERVED | RespIDData
 *   MACedIDForR = prf(SK_pr, RestOfRespIDPayload)
 *
 *   In particular, the initiator, but not the responder,
 *   authenticates the IKE_SA_INIT request (RealMessage1) and the
 *   responder, but not the initiator, authenticates the IKE_SA_INIT
 *   response (RealMessage2).  Thus, each side authenticates only the
 *   initial message it has sent and not the initial message it has
 *   received.
 *
 *   For the authentication calculations defined above, RealMessage1
 *   and RealMessage2 are the final accepted IKE_SA_INIT request and
 *   response.  If one or more prior IKE_SA_INIT exchanges were
 *   rejected and then restarted, for example due to COOKIE or
 *   INVALID_KE_PAYLOAD, those messages of the rejected exchanges are
 *   not included in the authenticated transcript.
 *
 * draft-ietf-ipsecme-ikev2-downgrade-prevention-08, "Protocol
 * Details":
 * https://www.ietf.org/archive/id/draft-ietf-ipsecme-ikev2-downgrade-prevention-08.html#name-protocol-details
 *
 * When a peer sent and received the IKE_SA_INIT_FULL_TRANSCRIPT_AUTH
 * notification, so both messages are covered, the received one first:
 *
 *   InitiatorSignedOctets = ZeroPrefix | RealMessage2
 *                           | RealMessage1 | NonceRData | MACedIDForI
 *   ResponderSignedOctets = ZeroPrefix | RealMessage1
 *                           | RealMessage2 | NonceIData | MACedIDForR
 *
 *   ZeroPrefix is 8 octets of zero.  ZeroPrefix serves a role of a
 *   domain separator making the new authentication blocks of data
 *   always different from authentication blocks of data defined in
 *   Section 2.15 of IKEv2 [RFC7296], because in both RealMessage1 and
 *   RealMessage2 the first 8 octets constitute IKE Initiator's SPI
 *   that can never be zero.
 */
void extract_v2AUTH_transcript(const struct ike_sa *ike,
			       enum perspective from_the_perspective_of,
			       struct v2AUTH_transcript *transcript)
{
	struct ro_hunk *me = ike->sa.st_firstpacket_me;
	struct ro_hunk *peer = ike->sa.st_firstpacket_peer;

	struct ro_hunk *sent =
		(from_the_perspective_of == LOCAL_PERSPECTIVE ? me :
		 from_the_perspective_of == REMOTE_PERSPECTIVE ? peer :
		 NULL);
	struct ro_hunk *received =
		(from_the_perspective_of == LOCAL_PERSPECTIVE ? peer :
		 from_the_perspective_of == REMOTE_PERSPECTIVE ? me :
		 NULL);

	*transcript = (struct v2AUTH_transcript) {0};
	if (ike->sa.st_v2_full_transcript_auth) {
		transcript->zero_prefix = THING_AS_SHUNK(v2AUTH_zero_prefix);
		transcript->message[0] = received;
		transcript->message[1] = sent;
	} else {
		transcript->message[0] = sent;
	}

	ldbg(ike->sa.logger, "v2AUTH transcript: %s",
	     (ike->sa.st_v2_full_transcript_auth ? "ZeroPrefix | received | sent" :
	      "sent"));
}

static void extract_v2AUTH_blobs(const struct ike_sa *ike,
				 const struct crypt_mac *idhash,
				 enum perspective from_the_perspective_of,
				 struct v2AUTH_blobs *blobs)
{
	struct logger *logger = ike->sa.logger;
	zero(blobs);

	enum sa_role role;
	struct hash_hunk *blob = blobs->blob;

	struct v2AUTH_transcript transcript;
	extract_v2AUTH_transcript(ike, from_the_perspective_of, &transcript);
	if (transcript.zero_prefix.len > 0) {
		*blob++ = (struct hash_hunk) { "zero-prefix", HUNK_REF(&transcript.zero_prefix), };
	}
	for (unsigned m = 0; m < elemsof(transcript.message); m++) {
		if (transcript.message[m] != NULL) {
			*blob++ = (struct hash_hunk) {
				(m == 0 ? "first-packet" : "second-packet"),
				HUNK_REF(transcript.message[m]),
			};
		}
	}

	switch (from_the_perspective_of) {
	case LOCAL_PERSPECTIVE:
		role = ike->sa.st_sa_role;
		break;
	case REMOTE_PERSPECTIVE:
		role = (ike->sa.st_sa_role == SA_INITIATOR ? SA_RESPONDER :
			ike->sa.st_sa_role == SA_RESPONDER ? SA_INITIATOR :
			0);
		break;
	default:
		bad_case(from_the_perspective_of);
	}

	/* inbound nonce */
	*blob++ = (role == SA_INITIATOR ? (struct hash_hunk) { "responder nonce", HUNK_REF(&ike->sa.st_nr), } :
		   role == SA_RESPONDER ? (struct hash_hunk) { "initiator nonce", HUNK_REF(&ike->sa.st_ni), } :
		   (struct hash_hunk) {0});

	passert(idhash->len == ike->sa.st_oakley.ta_prf->prf_output_size);
	*blob++ = (struct hash_hunk) { "idhash", HUNK_REF(idhash), };

	/* Include intermediate auth only if an IKE_INTERMEDIATE was processed. */
	if (ike->sa.st_v2_ike_intermediate.id != 0) {
		/*
		 * RFC 9242 3.3.2: both Initiator and Responder signed
		 * octets use IntAuth_iN | IntAuth_rN, independent of
		 * who is signing.
		 */
		*blob++ = (struct hash_hunk) { "IntAuth_*_I_A", HUNK_REF(&ike->sa.st_v2_ike_intermediate.initiator), };
		*blob++ = (struct hash_hunk) { "IntAuth_*_R_A", HUNK_REF(&ike->sa.st_v2_ike_intermediate.responder), };
		/* IKE AUTH's first Message ID */
		hton_thing(ike->sa.st_v2_ike_intermediate.id + 1, blobs->mid);
		shunk_t mid = THING_AS_SHUNK(blobs->mid);
		*blob++ = (struct hash_hunk) { "IKE_AUTH_MID", HUNK_REF(&mid), };
	}

	blobs->hunks.len = blob - blobs->blob;
	blobs->hunks.hunk = blobs->blob;
	PASSERT(logger, blobs->hunks.len <= elemsof(blobs->blob));

	if (LDBGP(DBG_CRYPT, logger)) {
		for (unsigned u = 0; u < blobs->hunks.len; u++) {
			struct hash_hunk *hunk = &blobs->blob[u];
			if (hunk->len > 0) {
				LDBG_log_hunk(logger, "%s:", hunk, hunk->name);
			}
		}
	}
}

struct crypt_mac v2_calculate_sighash(const struct ike_sa *ike,
				      const struct crypt_mac *idhash,
				      const struct hash_desc *hasher,
				      enum perspective from_the_perspective_of)
{
	struct v2AUTH_blobs blobs;
	extract_v2AUTH_blobs(ike, idhash, from_the_perspective_of, &blobs);
	return crypt_hash_hunks("sighash", hasher, &blobs.hunks, ike->sa.logger);
}

/*
 * Merge the configured auth with what was negotiated by the peer.
 */

struct authby local_v2_authby(struct ike_sa *ike)
{
	struct verbose verbose = VERBOSE(DEBUG_STREAM, ike->sa.logger, "digsig");
	struct connection *c = ike->sa.st_connection;
	const struct authby configured_authby = c->local->host.config->authby;
	struct authby negotiated_authby;
	const char *negotiation_story;
	bool override = false;

	if (ike->sa.st_v2_resume_session != NULL) {
		override = true;
		negotiation_story = "resume session";
		negotiated_authby = (struct authby) {
			AUTHBY_PSK,
		};
	} else if (ike->sa.st_eap != NULL) {
		override = true;
		negotiation_story = "eap";
		negotiated_authby = (struct authby) {
			AUTHBY_PSK,
		};
	} else if (ike->sa.st_peer_wants_null) {
		negotiation_story = "peer wants null";
		negotiated_authby = (struct authby) {
			AUTHBY_NULL,
		};
	} else if (!authby_is_set(ike->sa.st_v2_peer_authby)) {
		negotiation_story = "configured";
		negotiated_authby = configured_authby;
	} else {
		negotiated_authby = authby_and(configured_authby,
					       ike->sa.st_v2_peer_authby);
		if (authby_is_set(negotiated_authby)) {
			negotiation_story = "negotiated by SUPPORTED_AUTH_METHODS";
		} else {
			negotiated_authby = configured_authby;
			negotiation_story = "SUPPORTED_AUTH_METHODS negotiation failed, using configured";
			authby_buf sam, ca;
			vlog("no overlap between peer's supported %s and local configured %s authentication; SUPPORTED_AUTH_METHODS notification ignored",
			     str_authby(ike->sa.st_v2_peer_authby, &sam),
			     str_authby(configured_authby, &ca));
		}
	}
	authby_buf pab, cab, nab;
	vdbg("override %s configured %s negotiated %s proposed %s; %s",
	     bool_str(override),
	     str_authby(configured_authby, &cab),
	     str_authby(negotiated_authby, &nab),
	     str_authby(ike->sa.st_v2_peer_authby, &pab),
	     negotiation_story);
	vexpect(override || authby_has_any(configured_authby, negotiated_authby));
	return negotiated_authby;
}

/*
 * Map the configuration's authby=... onto the IKEv2 AUTH message's
 * auth method.
 */

static struct v2AUTH_method pubkey_v2AUTH_method(enum ikev2_auth_method method,
						 shunk_t blob,
						 const struct hash_desc *hash,
						 const struct pubkey_signer *signer)
{
	return (struct v2AUTH_method) {
		.method = method,
		.pubkey.blob = blob,
		.pubkey.hash = hash,
		.pubkey.signer = signer,
	};
}

static struct v2AUTH_method pubkey_v2AUTH_digsig_method(enum ikev2_auth_method method,
							const struct authby negotiated_authby,
							struct verbose verbose)
{
	/*
	 * Since caller picked digital signature, because the
	 * masked negotiated_authby had a digsig bit, there
	 * should be at least one plausible digital signature
	 * bit.
	 *
	 * However, this path can also be reached via an
	 * impair.  Hence out of an abundance of caution,
	 * re-mask the policy.
	 */
	struct authby digsig_authby =
		authby_and(negotiated_authby, authby_v2AUTH_digsig_payload());

	vdbg("selecting negotiated signer algorithm");
	unsigned level = ++verbose.level;
	FOR_EACH_ITEM(signer, &pubkey_blob_signers) {
		verbose.level = level+1;
		FOR_EACH_ITEM(blob, &(*signer)->digital_signature_blobs) {
			verbose.level = level+2;
			if (authby_has(digsig_authby, blob->auth)) {
				name_buf bab;
				vdbg("selected signer %s and blob %s:%s",
				     (*signer)->name,
				     str_name_short(&auth_names, blob->auth, &bab),
				     blob->hash->common.fqn);
				return pubkey_v2AUTH_method(method,
							    HUNK_AS_SHUNK(blob),
							    blob->hash, *signer);
			}

			name_buf bab;
			vdbg("skipping signer %s blob %s:%s as not negotiated",
			     (*signer)->name,
			     str_name_short(&auth_names, blob->auth, &bab),
			     blob->hash->common.fqn);
		}
		vdbg("skipping signer %s as not negotiated", (*signer)->name);
	}

	verbose.level = level;
	authby_buf ab;
	vlog_pexpect(HERE, "no compatible signature in %s",
		     str_authby(digsig_authby, &ab));

	return (struct v2AUTH_method) {
		.method = IKEv2_AUTH_RESERVED,
	};
}

static struct v2AUTH_method v2AUTH_method(struct ike_sa *ike,
					  const struct authby negotiated_authby,
					  enum ikev2_auth_method method)
{
	struct verbose verbose = VERBOSE(DEBUG_STREAM, ike->sa.logger, "digsig");
	switch (method) {
	case IKEv2_AUTH_DIGITAL_SIGNATURE:
	{
		/*
		 * Try to prefer the peer's authentication method.
		 */
		if (ike->sa.st_v2_initiator_auth.pubkey.hash != NULL &&
		    ike->sa.st_v2_initiator_auth.pubkey.signer != NULL) {
			/* could end up empty */
			struct authby signer_authby =
				authby_and(negotiated_authby,
					   ike->sa.st_v2_initiator_auth.pubkey.signer->authby);
			if (authby_has_hash(signer_authby, ike->sa.st_v2_initiator_auth.pubkey.hash)) {
				vdbg("using same hash %s and signer %s as peer",
				     ike->sa.st_v2_initiator_auth.pubkey.hash->common.fqn,
				     ike->sa.st_v2_initiator_auth.pubkey.signer->name);
				return pubkey_v2AUTH_method(method,
							    ike->sa.st_v2_initiator_auth.pubkey.blob,
							    ike->sa.st_v2_initiator_auth.pubkey.hash,
							    ike->sa.st_v2_initiator_auth.pubkey.signer);
			}
			authby_buf ab;
			vdbg("ignoring peer's hash %s and signer %s as the don't match local policy %s",
			     ike->sa.st_v2_initiator_auth.pubkey.hash->common.fqn,
			     ike->sa.st_v2_initiator_auth.pubkey.signer->name,
			     str_authby(negotiated_authby, &ab));
		}

		return pubkey_v2AUTH_digsig_method(method, negotiated_authby, verbose);
	}
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha1,
					    &signer_pubkey_rsassa_pkcs1_1_5_raw);
	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_256,
					    &signer_pubkey_ecdsa_raw/*_p256*/);
	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_384,
					    &signer_pubkey_ecdsa_raw/*_p384*/);
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_512,
					    &signer_pubkey_ecdsa_raw/*_p521*/);
	case IKEv2_AUTH_SHARED_KEY_MAC:
		return (struct v2AUTH_method) {
			.method = method,
			.psk.method = PSK_AUTH_SHARED_KEY,
		};
	case IKEv2_AUTH_NULL:
		return (struct v2AUTH_method) {
			.method = method,
			.psk.method = PSK_AUTH_NULL,
		};
	case IKEv2_AUTH_RESERVED:
	case IKEv2_AUTH_DSS_DIGITAL_SIGNATURE:
	case IKEv2_AUTH_GENERIC_SECURE_PASSWORD_AUTHENTICATION_METHOD:
		break;
	}
	bad_case(method);
}

struct v2AUTH_method local_v2AUTH_method(struct ike_sa *ike)
{
	struct connection *c = ike->sa.st_connection;
	struct authby negotiated_authby = local_v2_authby(ike);

	/*
	 * Narrow authby to what the private key can sign with. The
	 * method, hash and signer picked below must match the key.
	 *
	 * Only an end with a certificate or CKAID is narrowed, since
	 * those identify the key. An end with neither looks for any
	 * loaded key of the signer's type.
	 *
	 * A key whose type authby does not allow is ignored.
	 * PSK, NULL and EAP bits are kept.
	 */
	struct authby signature_authby = authby_v2AUTH_pubkey();
	bool cert_or_ckaid = (c->local->host.config->cert.nss_cert != NULL ||
			      c->local->host.config->ckaid != NULL);
	const struct secret_pubkey_stuff *pks = NULL;
	if (cert_or_ckaid && authby_has_v2AUTH_pubkey(negotiated_authby)) {
		pks = get_local_private_key_by_cert_or_ckaid(c, ike->sa.logger);
		if (pks != NULL) {
			struct authby key_authby = private_key_authby(pks, negotiated_authby);
			if (authby_has_any(key_authby, negotiated_authby)) {
				negotiated_authby = authby_and(negotiated_authby,
							       authby_or(key_authby,
									 authby_not(signature_authby)));
			} else {
				authby_buf ab;
				ldbg(ike->sa.logger,
				     "connection %s's private key has type %s but %s is needed",
				     c->name, pks->content.type->name,
				     str_authby(authby_and(negotiated_authby, signature_authby), &ab));
				pks = NULL;
			}
		}
	}

	if (impair.force_v2_auth_method.enabled) {
		name_buf eb;
		llog(IMPAIR_STREAM, ike->sa.logger, "forcing auth method %s",
		     str_enum_long(&ikev2_auth_method_names,
				   impair.force_v2_auth_method.value, &eb));
		return v2AUTH_method(ike, negotiated_authby,
				     impair.force_v2_auth_method.value);
	}

	if (!authby_is_set(negotiated_authby)) {
		authby_buf cb;
		llog_pexpect(ike->sa.logger, HERE,
			     "no authentication method matched %s",
			     str_authby(c->local->host.config->authby, &cb));
		return (struct v2AUTH_method) {
			.method = IKEv2_AUTH_RESERVED,
		};
	}

	/*
	 * Mask authby with the new "Digital Signature" hashes.  If
	 * any are valid, use that.
	 *
	 * If nothing matches, or the mask is empty, stumble on to one
	 * of the legacy authentication methods.
	 */
	struct authby digsig_authby =
		authby_and(negotiated_authby,
			   ike->sa.st_v2_digsig.peer_pubkey_mask);

	/*
	 * Fail when a signature method below would be picked but the
	 * certificate or CKAID has no usable private key.
	 * EAP, PSK and NULL need no key.
	 */
	if (cert_or_ckaid && pks == NULL &&
	    (authby_is_set(digsig_authby) ||
	     authby_has_any(negotiated_authby, (struct authby) {
				AUTHBY_RSASSA_PKCS1_V1_5_SHA1_RAW,
				AUTHBY_ECDSA_RAW,
			}))) {
		authby_buf ab;
		llog(RC_LOG, ike->sa.logger,
		     "local %s authentication has no usable private key",
		     str_authby(authby_and(negotiated_authby, signature_authby), &ab));
		return (struct v2AUTH_method) {
			.method = IKEv2_AUTH_RESERVED,
		};
	}

	if (authby_is_set(digsig_authby)) {
		return v2AUTH_method(ike, digsig_authby,
				     IKEv2_AUTH_DIGITAL_SIGNATURE);
	}

	if (authby_has(negotiated_authby,
		       AUTH_RSASSA_PKCS1_V1_5_SHA1_RAW)) {
		/*
		 * Local policy allows proof-of-identity using legacy
		 * RSASIG_v1_5.
		 */
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_RSA_DIGITAL_SIGNATURE);
	}

	/*
	 * Legacy ECDSA. For an end with a certificate or CKAID,
	 * negotiated_authby holds only the method for the key's
	 * curve if that method is allowed. Otherwise the first
	 * allowed method is used, and the peer may reject it.
	 */

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_512_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_512_P521);
	}

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_384_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_384_P384);
	}

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_256_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_256_P256);
	}

	if (authby_has(negotiated_authby, AUTH_EAPONLY)) {
		/*
		 * EAP-Only uses an EAP Generated KEY; which is
		 * bundled in PSK (it certainly isn't one of the
		 * signature payloads)?
		 */

		 */
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_SHARED_KEY_MAC);
	}

	if (authby_has(negotiated_authby, AUTH_PSK)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_SHARED_KEY_MAC);
	}

	if (authby_has(negotiated_authby, AUTH_NULL)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_NULL);
	}

	/*
	 * Since nothing is acceptable, try to log something helpful.
	 *
	 * For instance EdDSA is new-DIGSIG only.
	 */
	if (authby_has_v2AUTH_digsig_payload(negotiated_authby)) {
		authby_buf cb;
		llog(RC_LOG, ike->sa.logger,
		     "local Digital Signature authentication %s is not supported by peer",
		     str_authby(negotiated_authby, &cb));
	} else {
		authby_buf cb;
		llog_pexpect(ike->sa.logger, HERE,
			     "local %s authentication is not supported",
			     str_authby(negotiated_authby, &cb));
	}

	return (struct v2AUTH_method) {
		.method = IKEv2_AUTH_RESERVED,
	};
}

bool emit_local_v2AUTH(struct ike_sa *ike,
		       const struct hash_signature *auth_sig,
		       struct pbs_out *outs)
{
	struct ikev2_auth a = {
		.isaa_critical = build_ikev2_critical(false, ike->sa.logger),
		.isaa_auth_method = ike->sa.st_v2_local_auth.method,
	};

	struct pbs_out auth_pbs;
	if (!pbs_out_struct(outs, a, &ikev2_auth_desc, &auth_pbs)) {
		return false;
	}

	switch (ike->sa.st_v2_local_auth.method) {
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
	case IKEv2_AUTH_SHARED_KEY_MAC:
	case IKEv2_AUTH_NULL:
		if (!pbs_out_hunk(&auth_pbs, *auth_sig, "signature")) {
			return false;
		}
		break;

	case IKEv2_AUTH_DIGITAL_SIGNATURE:
	{
		/* saved during signing */
		shunk_t blob = ike->sa.st_v2_local_auth.pubkey.blob;

		if (pbad(blob.len == 0)) {
			return false;
		}

		if (!pbs_out_hunk(&auth_pbs, blob, "OID of ASN.1 Algorithm Identifier")) {
			/* already logged */
			return false;
		}

		if (!pbs_out_hunk(&auth_pbs, *auth_sig, "signature")) {
			/* already logged */
			return false;
		}
		break;
	}

	default:
		bad_case(a.isaa_auth_method);
	}

	close_pbs_out(&auth_pbs);
	return true;
}

/*
 * Called by process_v2_IKE_AUTH_request_tail() and
 * ikev2_in_IKE_AUTH_R() Do the actual AUTH payload verification
 *
 * ??? Several verify routines return an stf_status and yet we just
 *     return a bool.  We perhaps should return an stf_status so
 *     distinctions don't get lost.
 *
 * XXX: IKEv2 doesn't do subtle distinctions
 *
 * This just needs to answer the very simple yes/no question.  Did
 * auth succeed.  Caller needs to decide what response is appropriate.
 */

static diag_t verify_v2AUTH_and_log_using_pubkey(struct ike_sa *ike,
						 const struct crypt_mac *idhash,
						 const struct pbs_in *signature_pbs,
						 const struct hash_desc *hash_algo,
						 const struct pubkey_signer *pubkey_signer,
						 const char *signature_payload_name)
{
	statetime_t start = statetime_start(&ike->sa);
	struct connection *c = ike->sa.st_connection;

	authby_buf ab;
	ldbg(ike->sa.logger,
	     "verifying using hash %s and signer %s (%s)",
	     hash_algo->common.fqn,
	     pubkey_signer->name,
	     str_authby(pubkey_signer->authby, &ab));

	if (hash_algo->ikev2_alg_id < 0) {
		return diag("authentication failed: unknown or unsupported hash algorithm");
	}

	/*
	 * Strip the signer's allowed AUTHBYs back to just the HASH
	 * algorithm's AUTHBY.  EDDSA, say, uses the IDENTITY HASH.
	 *
	 * The result should be, at most, one bit (checked further
	 * down).
	 */
	struct authby sign_hash_bit = authby_and_hash(pubkey_signer->authby, hash_algo);
	unsigned count = authby_count(sign_hash_bit);

	if (pbad(count > 1)) {
		authby_buf ab;
		return diag("INTERNAL ERROR: too many authby bits set in %s",
			    str_authby(sign_hash_bit, &ab));
	}

	if (count == 0) {
		return diag("authentication failed: peer authentication requires hash algorithm %s",
			    hash_algo->common.fqn);
	}

	/*
	 * Does the configuration include the SIGN_HASH_BIT bit?
	 */
	if (!authby_has_all(c->remote->host.config->authby, sign_hash_bit)) {
		authby_buf pb;
		return diag("authentication failed: peer authentication requires policy %s",
			    str_authby(sign_hash_bit, &pb));
	}

	shunk_t signature = pbs_in_left(signature_pbs);
	if (signature.len == 0) {
		return diag("authentication failed: rejecting received zero-length signature");
	}

	struct v2AUTH_blobs blobs;
	extract_v2AUTH_blobs(ike, idhash, REMOTE_PERSPECTIVE, &blobs);
	struct crypt_mac hash = {0};
	if (hash_algo == &ike_alg_hash_identity) {
		llog(RC_LOG, ike->sa.logger, "identity hash, skipping hash calculation");
	} else {
		hash = crypt_hash_hunks("pubkey hash", hash_algo,
					&blobs.hunks, ike->sa.logger);
	}
	diag_t d = authsig_and_log_using_pubkey(ike, &hash, &blobs.hunks, signature,
						hash_algo, pubkey_signer,
						signature_payload_name);
	statetime_stop(&start, "%s()", __func__);
	return d;
}

diag_t verify_v2AUTH_and_log(enum ikev2_auth_method recv_auth,
			     struct ike_sa *ike,
			     const struct crypt_mac *idhash_in,
			     struct pbs_in *signature_pbs)
{
	const struct host_end_config *remote = &ike->sa.st_connection->remote->config->host;

	name_buf ramb;
	authby_buf rab;
	ldbg(ike->sa.logger,
	     "verifying auth payload, remote sent v2AUTH=%s we want and authby=%s",
	     str_enum_short(&ikev2_auth_method_names, recv_auth, &ramb),
	     str_authby(remote->authby, &rab));

	/*
	 * XXX: can the boiler plate check that THAT_AUTH matches
	 * recv_auth appearing in all case branches be merged?
	 */

	switch (recv_auth) {
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
		return verify_v2AUTH_and_log_using_pubkey(ike, idhash_in,
							  signature_pbs,
							  &ike_alg_hash_sha1,
							  &signer_pubkey_rsassa_pkcs1_1_5_raw,
							  NULL/*legacy-signature-name*/);

	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
		return verify_v2AUTH_and_log_using_pubkey(ike, idhash_in,
							  signature_pbs,
							  &ike_alg_hash_sha2_256,
							  &signer_pubkey_ecdsa_raw/*_p256*/,
							  NULL/*legacy-signature-name*/);

	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
		return verify_v2AUTH_and_log_using_pubkey(ike, idhash_in,
							  signature_pbs,
							  &ike_alg_hash_sha2_384,
							  &signer_pubkey_ecdsa_raw/*_p384*/,
							  NULL/*legacy-signature-name*/);
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
		return verify_v2AUTH_and_log_using_pubkey(ike, idhash_in,
							  signature_pbs,
							  &ike_alg_hash_sha2_512,
							  &signer_pubkey_ecdsa_raw/*_p521*/,
							  NULL/*legacy-signature-name*/);

	case IKEv2_AUTH_SHARED_KEY_MAC:
	{
		if (!authby_has(remote->authby, AUTH_PSK) &&
		    ike->sa.st_v2_resume_session == NULL) {
			/*
			 * XXX: session resume forces PSK, so
			 * presumably peer has done that.
			 */
			authby_buf an;
			return diag("authentication failed: peer attempted PSK authentication but we want %s",
				    str_authby(remote->authby, &an));
		}

		diag_t d = verify_v2AUTH_and_log_using_psk(PSK_AUTH_SHARED_KEY,
							   ike, idhash_in,
							   signature_pbs,
							   NULL/*auth_sig*/);
		if (d != NULL) {
			ldbg(ike->sa.logger, "authentication failed: PSK AUTH mismatch");
			return d;
		}

		return NULL;
	}

	case IKEv2_AUTH_NULL:
	{
		if (!authby_has(remote->authby, AUTH_NULL)) {
			authby_buf an;
			return diag("authentication failed: peer attempted NULL authentication but we want %s",
				    str_authby(remote->authby, &an));
		}

		diag_t d = verify_v2AUTH_and_log_using_psk(PSK_AUTH_NULL, ike, idhash_in,
							   signature_pbs, NULL/*auth_sig*/);
		if (d != NULL) {
			ldbg(ike->sa.logger, "authentication failed: NULL AUTH mismatch (implementation bug?)");
			return d;
		}

		ike->sa.st_ikev2_anon = true;
		return NULL;
	}

	case IKEv2_AUTH_DIGITAL_SIGNATURE:
	{
		if (!authby_has_v2AUTH_digsig_payload(remote->authby)) {
			authby_buf an;
			return diag("authentication failed: peer attempted authentication through Digital Signature but we want %s",
				    str_authby(remote->authby, &an));
		}

		shunk_t signature = pbs_in_left(signature_pbs);

		/*
		 * Try to match ASN.1 blob designating the hash
		 * algorithm.
		 *
		 * For all signers that match the peer's allowed
		 * authby, try the signer's hashes blobs.
		 */

		FOR_EACH_ITEM(sp, &pubkey_blob_signers) {
			const struct pubkey_signer *signer = (*sp);

			/*
			 * Only consider auth+hash allowed by this
			 * signer, assuming there are some.
			 */
			struct authby signer_hashes = authby_and(remote->authby, signer->authby);
			if (!authby_is_set(signer_hashes)) {
				authby_buf rab;
				ldbg(ike->sa.logger, "digsig: signer %s does not match authby %s",
				     signer->name,
				     str_authby(remote->authby, &rab));
				continue;
			}

			/*
			 * Now iterate through the hashes supported by
			 * this signer and allowed by remote->auth; is
			 * there a more efficient way of doing this.
			 */

			authby_buf sab;
			ldbg(ike->sa.logger,
			     "digsig: signer %s matches authby %s, looking for blob matching DIGSIG hashes %s",
			     signer->name,
			     str_authby(remote->authby, &rab),
			     str_authby(signer_hashes, &sab));

			FOR_EACH_ITEM(blob, &signer->digital_signature_blobs) {

				/*
				 * Do the signer and remote->authby
				 * allow the blob's authentication
				 * method?
				 */
				if (!authby_has(signer_hashes, blob->auth)) {
					name_buf an;
					authby_buf sab;
					ldbg(ike->sa.logger, "digsig:   signer %s blob %s:%s does not match authby %s",
					     signer->name,
					     str_name_short(&auth_names, blob->auth, &an),
					     blob->hash->common.fqn,
					     str_authby(signer_hashes, &sab));
					continue;
				}

				PEXPECT(ike->sa.logger, authby_has_hash(signer_hashes, blob->hash));
				if (pbad(blob->len == 0)) {
					continue;
				}

				if (!hunk_starteq(signature, *blob)) {
					name_buf an;
					ldbg(ike->sa.logger,
					     "digsig:     skipping signer %s blob %s:%s as it doesn't match AUTH payload",
					     signer->name,
					     str_name_short(&auth_names, blob->auth, &an),
					     blob->hash->common.fqn);
					continue;
				};

				name_buf an;
				ldbg(ike->sa.logger,
				     "digsig:    using signer %s and blob %s:%s",
				     signer->name,
				     str_name_short(&auth_names, blob->auth, &an),
				     blob->hash->common.fqn);

				/* eat the blob */
				shunk_t ignore;
				diag_t d = pbs_in_shunk(signature_pbs,
							blob->len,
							&ignore,
							"skip ASN.1 blob for hash algo");
				if (d != NULL) {
					ldbg(ike->sa.logger,
					     "digsig:     failing signer %s due to I/O error: %s",
					     signer->name, str_diag(d));
					return d;
				}

				/*
				 * Save the choice so that the
				 * responder can prefer the same
				 * values.
				 */
				ike->sa.st_v2_initiator_auth = (struct v2AUTH_method) {
					.method = recv_auth,
					.pubkey.blob = HUNK_AS_SHUNK(blob),
					.pubkey.hash = blob->hash,
					.pubkey.signer = signer,
				};

				return verify_v2AUTH_and_log_using_pubkey(ike, idhash_in,
									  signature_pbs,
									  blob->hash,
									  signer,
									  "digital signature");
			}
		}

		ldbg(ike->sa.logger, "digsig:   no match");
		authby_buf an;
		return diag("authentication failed: no acceptable ECDSA/RSA-PSS ASN.1 signature hash proposal included for %s",
			    str_authby(remote->authby, &an));

	}
	default:
	{
		name_buf eb;
		return diag("authentication failed: method %s not supported",
			    str_enum_long(&ikev2_auth_method_names, recv_auth, &eb));
	}
	}
}

bool submit_local_v2AUTH_signature_generator(struct ike_sa *ike,
					     struct msg_digest *md,
					     v2_auth_signature_cb *cb)
{
	struct logger *logger = ike->sa.logger;
	ike->sa.st_v2_local_auth = local_v2AUTH_method(ike);

	switch (ike->sa.st_v2_local_auth.method) {
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
	case IKEv2_AUTH_DIGITAL_SIGNATURE:
		return submit_local_v2AUTH_signature(ike, md,
						     &ike->sa.st_v2_id_payload.mac,
						     cb, HERE);

	case IKEv2_AUTH_SHARED_KEY_MAC:
	case IKEv2_AUTH_NULL:
	{
		struct crypt_mac signed_octets = empty_mac;
		diag_t d = ikev2_calculate_psk_sighash(ike->sa.st_v2_local_auth.psk.method,
						       LOCAL_PERSPECTIVE,
						       /*accumulated EAP hash*/NULL,
						       ike, &ike->sa.st_v2_id_payload.mac,
						       &signed_octets);
		if (d != NULL) {
			llog(RC_LOG, ike->sa.logger, "%s", str_diag(d));
			pfree_diag(&d);
			return false;
		}

		if (LDBGP(DBG_CRYPT, logger)) {
			LDBG_log_hunk(logger, "PSK auth octets:", &signed_octets);
		}

		/*
		 * The big fake.  This should offload the above, but
		 * the code isn't ready.
		 */
		if (!submit_local_v2AUTH_signature(ike, md, &signed_octets,
						   cb, HERE)) {
			ldbg(ike->sa.logger, "submit_v2_auth_signature() died, fatal");
			return false;
		}

		return true;
	}

	default:
	{
		name_buf eb;
		llog_sa(RC_LOG, ike,
			"authentication method %s not supported",
			str_enum_long(&ikev2_auth_method_names,
				      ike->sa.st_v2_local_auth.method, &eb));
		return false;
	}
	}

}

/*
 * Construct the ID[ir] payload and store it in state so that it can
 * be emitted later.  Then use that to construct the "MACedIDFor[IR]".
 *
 * Code assumes that struct ikev2_id's "IDType|RESERVED" is laid out
 * the same as the packet.
 */

static struct crypt_mac v2_hash_id_payload(const char *id_name, const struct ike_sa *ike,
					   const char *key_name, PK11SymKey *key)
{
	/*
	 * InitiatorIDPayload = PayloadHeader | RestOfInitIDPayload
	 * RestOfInitIDPayload = IDType | RESERVED | InitIDData
	 * MACedIDForR = prf(SK_pr, RestOfInitIDPayload)
	 */
	struct crypt_prf *id_ctx = crypt_prf_init_symkey(id_name, ike->sa.st_oakley.ta_prf,
							 key_name, key, ike->sa.logger);
	/* skip PayloadHeader; hash: IDType | RESERVED */
	crypt_prf_update_bytes(id_ctx, "IDType", &ike->sa.st_v2_id_payload.header.isai_type,
				sizeof(ike->sa.st_v2_id_payload.header.isai_type));
	/* note that res1+res2 is 3 zero bytes */
	crypt_prf_update_byte(id_ctx, "RESERVED 1", ike->sa.st_v2_id_payload.header.isai_res1);
	crypt_prf_update_byte(id_ctx, "RESERVED 2", ike->sa.st_v2_id_payload.header.isai_res2);
	crypt_prf_update_byte(id_ctx, "RESERVED 3", ike->sa.st_v2_id_payload.header.isai_res3);
	/* hash: InitIDData */
	crypt_prf_update_hunk(id_ctx, "InitIDData", ike->sa.st_v2_id_payload.data);
	return crypt_prf_final_mac(&id_ctx, NULL/*no-truncation*/);
}

void v2_IKE_AUTH_responder_id_payload(struct ike_sa *ike)
{
	struct connection *const c = ike->sa.st_connection;

	if (ike->sa.st_peer_wants_null) {
		/* make it the Null ID */
		ike->sa.st_v2_id_payload.header.isai_type = ID_NULL;
		ike->sa.st_v2_id_payload.data = empty_chunk;
	} else {
		shunk_t data;
		ike->sa.st_v2_id_payload.header =
			build_v2_id_payload(&c->local->host, &data,
					    "my IDr", ike->sa.logger);
		ike->sa.st_v2_id_payload.data = clone_hunk_as_chunk(&data, "my IDr");
	}

	/* will be signed in auth payload */
	ike->sa.st_v2_id_payload.mac = v2_hash_id_payload("IDr", ike, "st_skey_pr_nss",
					    ike->sa.st_skey_pr_nss);
}

void v2_IKE_AUTH_initiator_id_payload(struct ike_sa *ike)
{
	struct connection *c = ike->sa.st_connection;

	shunk_t data;
	ike->sa.st_v2_id_payload.header =
		build_v2_id_payload(&c->local->host, &data,
				    "my IDi", ike->sa.logger);
	ike->sa.st_v2_id_payload.data = clone_hunk_as_chunk(&data, "my IDi");

	ike->sa.st_v2_id_payload.mac = v2_hash_id_payload("IDi", ike,
					    "st_skey_pi_nss",
					    ike->sa.st_skey_pi_nss);
	if (ike->sa.st_v2_ike_ppk == PPK_IKE_AUTH && !c->config->ppk.insist) {
		/* ID payload that we've build is the same */
		ike->sa.st_v2_id_payload.mac_no_ppk_auth =
			v2_hash_id_payload("IDi (no-PPK)", ike,
					   "sk_pi_no_pkk",
					   ike->sa.st_sk_pi_no_ppk);
	}
}

struct crypt_mac v2_remote_id_hash(const struct ike_sa *ike,
				   const char *why,
				   const struct msg_digest *md)
{
	/*
	 * Computing hash according to peer, hence initiator uses
	 * responder's IDr payload and responder's secret, and
	 * vis-vis.
	 */

	PK11SymKey *key;
	const struct pbs_in *id_pbs;
	const char *key_name;
	const char *id_name;
	switch (ike->sa.st_sa_role) {
	case SA_INITIATOR:
		key_name = "st_skey_pr_nss";
		key = ike->sa.st_skey_pr_nss;
		id_name = "IDr";
		id_pbs = &md->chain[NEXT_PAYLOAD_v2IDr]->pbs;
		break;
	case SA_RESPONDER:
		key_name = "st_skey_pi_nss";
		key = ike->sa.st_skey_pi_nss;
		id_name = "IDi";
		id_pbs = &md->chain[NEXT_PAYLOAD_v2IDi]->pbs;
		break;
	default:
		bad_case(ike->sa.st_sa_role);
	}

	shunk_t id_payload = pbs_in_all(id_pbs);
	const uint8_t *id_start = id_payload.ptr;
	size_t id_size = id_payload.len;
	/* HASH of ID is not done over common header */
	id_start += NSIZEOF_isakmp_generic;
	id_size -= NSIZEOF_isakmp_generic;
	struct crypt_prf *id_ctx = crypt_prf_init_symkey(why, ike->sa.st_oakley.ta_prf,
							 key_name, key, ike->sa.logger);
	crypt_prf_update_bytes(id_ctx, id_name, id_start, id_size);
	return crypt_prf_final_mac(&id_ctx, NULL/*no-truncation*/);
}

/*
 * Convert the proposed connections into something this responder
 * might accept.
 *
 * + DIGITAL_SIGNATURE code seems a bit dodgy, should this be looking
 * inside the auth proposal to see what is actually required?
 *
 * + the legacy ECDSA_SHA2* methods also seem to be a bit dodgy,
 * shouldn't they also specify the SHA algorithm so that can be
 * matched?
 */

struct authby proposed_v2AUTH(struct ike_sa *ike,
			      struct msg_digest *md)
{
	enum ikev2_auth_method atype =
		md->chain[NEXT_PAYLOAD_v2AUTH]->payload.v2auth.isaa_auth_method;
	name_buf nb;
	ldbg(ike->sa.logger, "converting v2AUTH %s into authbys set",
	     str_enum_short(&ikev2_auth_method_names, atype, &nb));

	switch (atype) {
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
		return authby_from_auth(AUTH_RSASSA_PKCS1_V1_5_SHA1_RAW);
	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
		return authby_from_auth(AUTH_ECDSA_SHA2_256_RAW);
	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
		return authby_from_auth(AUTH_ECDSA_SHA2_384_RAW);
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
		return authby_from_auth(AUTH_ECDSA_SHA2_512_RAW);
	case IKEv2_AUTH_SHARED_KEY_MAC:
		return (struct authby) {
			AUTHBY_PSK,
		};
	case IKEv2_AUTH_NULL:
		return (struct authby) {
			AUTHBY_NULL,
		};
	case IKEv2_AUTH_DIGITAL_SIGNATURE:
		return authby_v2AUTH_digsig_payload();
	default:
	{
		name_buf nb;
		llog(RC_LOG, ike->sa.logger, "auth method %s unrecognized",
		     str_enum_short(&ikev2_auth_method_names,
				    atype, &nb));
		return (struct authby) {0};
	}
	}
}

size_t jam_authby(struct jambuf *buf, struct authby authby)
{
	return jam_authby_raw(buf, authby, /*human*/false);
}

size_t jam_authby_auth(struct jambuf *buf, struct authby authby)
{
	return jam_authby_raw(buf, authby, /*human*/true);
}

const char *str_authby(struct authby authby, authby_buf *buf)
{
	struct jambuf jambuf = ARRAY_AS_JAMBUF(buf->buf);
	jam_authby(&jambuf, authby);
	return buf->buf;
}

const char *str_authby_auth(struct authby authby, authby_buf *buf)
{
	struct jambuf jambuf = ARRAY_AS_JAMBUF(buf->buf);
	jam_authby_auth(&jambuf, authby);
	return buf->buf;
}

