		override = true;
		negotiation_story = "eap";
		negotiated_authby = (struct authby) {
			AUTHBY_PSK,
		};
	} else if (ike->sa.st_peer_wants_null) {
		negotiation_story = "peer wants null";
		negotiated_authby = (struct authby) {
			AUTHBY_NULL,
