	     str_authby(ike->sa.st_v2_peer_authby, &pab),
	     negotiation_story);
	vexpect(override || authby_has_any(configured_authby, negotiated_authby));
	return negotiated_authby;
}

/*
 * Map the configuration's authby=... onto the IKEv2 AUTH message's
 * auth method.
 */

static struct v2AUTH_method pubkey_v2AUTH_method(enum ikev2_auth_method method,
						 shunk_t blob,
						 const struct hash_desc *hash,
						 const struct pubkey_signer *signer)
{
	return (struct v2AUTH_method) {
		.method = method,
		.pubkey.blob = blob,
		.pubkey.hash = hash,
		.pubkey.signer = signer,
	};
}

static struct v2AUTH_method pubkey_v2AUTH_digsig_method(enum ikev2_auth_method method,
							const struct authby negotiated_authby,
							struct verbose verbose)
{
	/*
	 * Since caller picked digital signature, because the
	 * masked negotiated_authby had a digsig bit, there
	 * should be at least one plausible digital signature
	 * bit.
	 *
	 * However, this path can also be reached via an
	 * impair.  Hence out of an abundance of caution,
	 * re-mask the policy.
	 */
	struct authby digsig_authby =
		authby_and(negotiated_authby, authby_v2AUTH_digsig_payload());

	vdbg("selecting negotiated signer algorithm");
	unsigned level = ++verbose.level;
	FOR_EACH_ITEM(signer, &pubkey_blob_signers) {
		verbose.level = level+1;
		FOR_EACH_ITEM(blob, &(*signer)->digital_signature_blobs) {
			verbose.level = level+2;
			if (authby_has(digsig_authby, blob->auth)) {
				name_buf bab;
				vdbg("selected signer %s and blob %s:%s",
				     (*signer)->name,
				     str_name_short(&auth_names, blob->auth, &bab),
				     blob->hash->common.fqn);
				return pubkey_v2AUTH_method(method,
							    HUNK_AS_SHUNK(blob),
							    blob->hash, *signer);
			}

			name_buf bab;
			vdbg("skipping signer %s blob %s:%s as not negotiated",
			     (*signer)->name,
			     str_name_short(&auth_names, blob->auth, &bab),
			     blob->hash->common.fqn);
		}
		vdbg("skipping signer %s as not negotiated", (*signer)->name);
	}

	verbose.level = level;
	authby_buf ab;
	vlog_pexpect(HERE, "no compatible signature in %s",
		     str_authby(digsig_authby, &ab));

	return (struct v2AUTH_method) {
		.method = IKEv2_AUTH_RESERVED,
	};
}

static struct v2AUTH_method v2AUTH_method(struct ike_sa *ike,
					  const struct authby negotiated_authby,
					  enum ikev2_auth_method method)
{
	struct verbose verbose = VERBOSE(DEBUG_STREAM, ike->sa.logger, "digsig");
	switch (method) {
	case IKEv2_AUTH_DIGITAL_SIGNATURE:
	{
		/*
		 * Try to prefer the peer's authentication method.
		 */
		if (ike->sa.st_v2_initiator_auth.pubkey.hash != NULL &&
		    ike->sa.st_v2_initiator_auth.pubkey.signer != NULL) {
			/* could end up empty */
			struct authby signer_authby =
				authby_and(negotiated_authby,
					   ike->sa.st_v2_initiator_auth.pubkey.signer->authby);
			if (authby_has_hash(signer_authby, ike->sa.st_v2_initiator_auth.pubkey.hash)) {
				vdbg("using same hash %s and signer %s as peer",
				     ike->sa.st_v2_initiator_auth.pubkey.hash->common.fqn,
				     ike->sa.st_v2_initiator_auth.pubkey.signer->name);
				return pubkey_v2AUTH_method(method,
							    ike->sa.st_v2_initiator_auth.pubkey.blob,
							    ike->sa.st_v2_initiator_auth.pubkey.hash,
							    ike->sa.st_v2_initiator_auth.pubkey.signer);
			}
			authby_buf ab;
			vdbg("ignoring peer's hash %s and signer %s as the don't match local policy %s",
			     ike->sa.st_v2_initiator_auth.pubkey.hash->common.fqn,
			     ike->sa.st_v2_initiator_auth.pubkey.signer->name,
			     str_authby(negotiated_authby, &ab));
		}

		return pubkey_v2AUTH_digsig_method(method, negotiated_authby, verbose);
	}
	case IKEv2_AUTH_RSA_DIGITAL_SIGNATURE:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha1,
					    &signer_pubkey_rsassa_pkcs1_1_5_raw);
	case IKEv2_AUTH_ECDSA_SHA2_256_P256:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_256,
					    &signer_pubkey_ecdsa_raw/*_p256*/);
	case IKEv2_AUTH_ECDSA_SHA2_384_P384:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_384,
					    &signer_pubkey_ecdsa_raw/*_p384*/);
	case IKEv2_AUTH_ECDSA_SHA2_512_P521:
		return pubkey_v2AUTH_method(method,
					    (shunk_t) {0},
					    &ike_alg_hash_sha2_512,
					    &signer_pubkey_ecdsa_raw/*_p521*/);
	case IKEv2_AUTH_SHARED_KEY_MAC:
		return (struct v2AUTH_method) {
			.method = method,
			.psk.method = PSK_AUTH_SHARED_KEY,
		};
	case IKEv2_AUTH_NULL:
		return (struct v2AUTH_method) {
			.method = method,
			.psk.method = PSK_AUTH_NULL,
		};
	case IKEv2_AUTH_RESERVED:
	case IKEv2_AUTH_DSS_DIGITAL_SIGNATURE:
	case IKEv2_AUTH_GENERIC_SECURE_PASSWORD_AUTHENTICATION_METHOD:
		break;
	}
	bad_case(method);
}

struct v2AUTH_method local_v2AUTH_method(struct ike_sa *ike)
{
	struct connection *c = ike->sa.st_connection;
	struct authby negotiated_authby = local_v2_authby(ike);

	/*
	 * Narrow authby to what the private key can sign with. The
	 * method, hash and signer picked below must match the key.
	 *
	 * Only an end with a certificate or CKAID is narrowed, since
	 * those identify the key. An end with neither looks for any
	 * loaded key of the signer's type.
	 *
	 * A key whose type authby does not allow is ignored.
	 * PSK, NULL and EAP bits are kept.
	 */
	struct authby signature_authby = authby_v2AUTH_pubkey();
	bool cert_or_ckaid = (c->local->host.config->cert.nss_cert != NULL ||
			      c->local->host.config->ckaid != NULL);
	const struct secret_pubkey_stuff *pks = NULL;
	if (cert_or_ckaid && authby_has_v2AUTH_pubkey(negotiated_authby)) {
		pks = get_local_private_key_by_cert_or_ckaid(c, ike->sa.logger);
		if (pks != NULL) {
			struct authby key_authby = private_key_authby(pks, negotiated_authby);
			if (authby_has_any(key_authby, negotiated_authby)) {
				negotiated_authby = authby_and(negotiated_authby,
							       authby_or(key_authby,
									 authby_not(signature_authby)));
			} else {
				authby_buf ab;
				ldbg(ike->sa.logger,
				     "connection %s's private key has type %s but %s is needed",
				     c->name, pks->content.type->name,
				     str_authby(authby_and(negotiated_authby, signature_authby), &ab));
				pks = NULL;
			}
		}
	}

	if (impair.force_v2_auth_method.enabled) {
		name_buf eb;
		llog(IMPAIR_STREAM, ike->sa.logger, "forcing auth method %s",
		     str_enum_long(&ikev2_auth_method_names,
				   impair.force_v2_auth_method.value, &eb));
		return v2AUTH_method(ike, negotiated_authby,
				     impair.force_v2_auth_method.value);
	}

	if (!authby_is_set(negotiated_authby)) {
		authby_buf cb;
		llog_pexpect(ike->sa.logger, HERE,
			     "no authentication method matched %s",
			     str_authby(c->local->host.config->authby, &cb));
		return (struct v2AUTH_method) {
			.method = IKEv2_AUTH_RESERVED,
		};
	}

	/*
	 * Mask authby with the new "Digital Signature" hashes.  If
	 * any are valid, use that.
	 *
	 * If nothing matches, or the mask is empty, stumble on to one
	 * of the legacy authentication methods.
	 */
	struct authby digsig_authby =
		authby_and(negotiated_authby,
			   ike->sa.st_v2_digsig.peer_pubkey_mask);

	/*
	 * Fail when a signature method below would be picked but the
	 * certificate or CKAID has no usable private key.
	 * EAP, PSK and NULL need no key.
	 */
	if (cert_or_ckaid && pks == NULL &&
	    (authby_is_set(digsig_authby) ||
	     authby_has_any(negotiated_authby, (struct authby) {
				AUTHBY_RSASSA_PKCS1_V1_5_SHA1_RAW,
				AUTHBY_ECDSA_RAW,
			}))) {
		authby_buf ab;
		llog(RC_LOG, ike->sa.logger,
		     "local %s authentication has no usable private key",
		     str_authby(authby_and(negotiated_authby, signature_authby), &ab));
		return (struct v2AUTH_method) {
			.method = IKEv2_AUTH_RESERVED,
		};
	}

	if (authby_is_set(digsig_authby)) {
		return v2AUTH_method(ike, digsig_authby,
				     IKEv2_AUTH_DIGITAL_SIGNATURE);
	}

	if (authby_has(negotiated_authby,
		       AUTH_RSASSA_PKCS1_V1_5_SHA1_RAW)) {
		/*
		 * Local policy allows proof-of-identity using legacy
		 * RSASIG_v1_5.
		 */
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_RSA_DIGITAL_SIGNATURE);
	}

	/*
	 * Legacy ECDSA. For an end with a certificate or CKAID,
	 * negotiated_authby holds only the method for the key's
	 * curve if that method is allowed. Otherwise the first
	 * allowed method is used, and the peer may reject it.
	 */

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_512_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_512_P521);
	}

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_384_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_384_P384);
	}

	if (authby_has(negotiated_authby, AUTH_ECDSA_SHA2_256_RAW)) {
		return v2AUTH_method(ike, /*ignored*/(struct authby){0},
				     IKEv2_AUTH_ECDSA_SHA2_256_P256);
	}

