						  const struct msg_digest *md)
{
	PEXPECT(ike->sa.logger, v2_msg_role(md) == MESSAGE_RESPONSE);
	LLOG_JAMBUF(RC_LOG, ike->sa.logger, buf) {

		jam_string(buf, "processed IKE_SA_INIT response from ");
		jam_endpoint_address_protocol_port_sensitive(buf, &md->sender);
		jam_string(buf, " ");

		jam_v2_ike_protection(buf, ike);

		jam_string(buf, ", initiating ");
		enum ikev2_exchange ix =
			(next_is_ikev2_ike_intermediate_exchange(ike) ? ISAKMP_v2_IKE_INTERMEDIATE :
			 ISAKMP_v2_IKE_AUTH);
		jam_enum_short(buf, &ikev2_exchange_names, ix);
	}
}

static bool save_v2N_SIGNATURE_HASH_ALGORITHMS(struct ike_sa *ike,
					       const struct msg_digest *md)
{
	if (md->v2N_status[v2N_status_SIGNATURE_HASH_ALGORITHMS] == NULL) {
		/* nothing to save */
		return true;
	}

	if (ikev2_signature_hash_algorithms == YNA_NO) {
		llog(RC_LOG, ike->sa.logger, "ignoring SIGNATURE_HASH_ALGORITHMS notification");
		return true;
	}

	struct pbs_in pbs = md->v2N_status[v2N_status_SIGNATURE_HASH_ALGORITHMS]->pbs;
	ike->sa.st_seen_hashnotify = true;
	while (pbs_left(&pbs) > 0) {

		uint16_t nh_value;
		passert(sizeof(nh_value) == RFC_7427_HASH_ALGORITHM_IDENTIFIER_SIZE);
		diag_t d = pbs_in_thing(&pbs, nh_value,
					"hash algorithm identifier (network ordered)");
		if (d != NULL) {
			llog(RC_LOG, ike->sa.logger, "%s", str_diag(d));
			pfree_diag(&d);
			return false;
		}

		enum ikev2_hash_algorithm h_value = ntohs(nh_value);
		name_buf b;
		const struct hash_desc *hash = ikev2_hash_desc(h_value, &b);
		if (hash == NULL) {
			llog(RC_LOG, ike->sa.logger, "received and ignored unknown hash algorithm %s", b.buf);
			continue;
		}

		struct authby peer_pubkey_mask =
			authby_and_hash(authby_v2AUTH_digsig_payload(), hash);
		if (!authby_is_set(peer_pubkey_mask)) {
			ldbg(ike->sa.logger, "digsig: received and ignored unacceptable pubkey hash algorithm %s", hash->common.fqn);
			continue;
		}

		authby_buf ab;
		ldbg(ike->sa.logger, "digsig: received and accepted hash algorithm %s; adding %s",
		     hash->common.fqn, str_authby(peer_pubkey_mask, &ab));
		ike->sa.st_v2_digsig.peer_pubkey_mask =
			authby_or(ike->sa.st_v2_digsig.peer_pubkey_mask,
				  peer_pubkey_mask);
	}
	return true;
}

bool calc_v2_new_ike_keymat(struct ike_sa *ike,
			    const ike_spis_t *new_ike_spis,
			    where_t where)
{
	struct logger *logger = ike->sa.logger;
	PK11SymKey *shared = ike->sa.st_dh_shared_secret;
	const struct prf_desc *prf = ike->sa.st_oakley.ta_prf;

	ldbg(logger, "%s() calculating skeyseed using prf=%s",
	     __func__, prf->common.fqn);

	/* generate SKEYSEED from key=(Ni|Nr), hash of shared */
	PK11SymKey *skeyseed = ikev2_IKE_SA_INIT_skeyseed(prf, ike->sa.st_ni, ike->sa.st_nr,
							  shared, logger);
	if (skeyseed == NULL) {
		llog_pexpect(logger, where, "rekey SKEYSEED failed");
		return false;
	}

	calc_v2_ike_keymat(&ike->sa, skeyseed, new_ike_spis);
	symkey_delref(logger, "skeyseed", &skeyseed);
	return true;
}

