bool record_v2_IKE_SA_INIT_request(struct ike_sa *ike)
{
	struct connection *c = ike->sa.st_connection;

	struct v2_message request;
	if (!open_v2_message("IKE_SA_INIT request",
			     ike, ike->sa.logger, NULL/*request*/,
			     ISAKMP_v2_IKE_SA_INIT,
			     reply_buffer, sizeof(reply_buffer),
			     &request, UNENCRYPTED_PAYLOAD)) {
		return false;
	}

	switch (impair.ddos_cookie) {
	case IMPAIR_DDOS_COOKIE_ADD:
		if (ike->sa.st_dcookie.ptr == NULL) {
			llog(IMPAIR_STREAM, ike->sa.logger, "adding unsolicited and mangled DDOS cookie");
			uint8_t byte = 0;
			messupn(&byte, sizeof(byte));
			replace_chunk(&ike->sa.st_dcookie, THING_AS_SHUNK(byte), "mangled dcookie");
		}
		break;
	case IMPAIR_DDOS_COOKIE_MANGLE:
		/* add or mangle a dcookie so what we will send is bogus */
		if (ike->sa.st_dcookie.ptr != NULL) {
		}
		break;
	case YNA_NO:
		ldbg(ike->sa.logger, "send-signature-hash_algorithms? NO");
		break;
	case YNA_AUTO:
		if (authby_has_v2AUTH_digsig_payload(c->local->host.config->authby) ||
		    authby_has_v2AUTH_digsig_payload(c->remote->host.config->authby)) {
			ldbg(ike->sa.logger, "send-signature-hash_algorithms=auto? YES");
			if (!emit_v2N_SIGNATURE_HASH_ALGORITHMS(request.pbs)) {
				return false;
			}
			break;
		}
		ldbg(ike->sa.logger, "send-signature-hash_algorithms=auto? NO");
		break;
	case YNA_UNSET:
		bad_case(ikev2_signature_hash_algorithms);
	}

	/* Send NAT-T Notify payloads */
	if (!ikev2_out_nat_v2n(request.pbs, &ike->sa, &zero_ike_spi/*responder unknown*/))
		return false;

	/* From here on, only payloads left are Vendor IDs */
	if (c->config->host.send_vendorid) {
		if (!emit_v2V(request.pbs, config_setup_vendorid()))
			return false;
	}

	if (c->config->host.send_vid_fake_strongswan) {
		if (!emit_v2VID(request.pbs, VID_STRONGSWAN))
			return false;
	}

	/*
	 * Announce to the world that this end likes NULL
	 * authentication (either accepts NULL authentication or is
	 * going to use to authenticate).
	 *
	 * XXX: is announcing to the world that this end accepts NULL
	 * authentication really a good idea?
	 *
	 * XXX: should this check POLICY_OPPORTUNISTIC?
	 */
	if (authby_has(c->local->host.config->authby, AUTH_NULL) ||
	    authby_has(c->remote->host.config->authby, AUTH_NULL)) {
		if (!emit_v2VID(request.pbs, VID_OPPORTUNISTIC))
			return false;
	}

	if (!close_and_record_v2_message(&request)) {
		return false;
	}

	/* save packet for later signing */
	save_first_outbound_ikev2_packet("IKE_SA_INIT request",
					 ike, &request);

	return true;
}

