		uint8_t hash_id[RFC_7427_HASH_ALGORITHM_IDENTIFIER_SIZE];
		hton_thing(hash->ikev2_alg_id, hash_id);
		if (!pbs_out_thing(pbs, hash_id,
				   "hash algorithm identifier")) {
			/* already logged */
			return false;
		}
	}
	return true;
