struct ikev2_task {
	/* in */
	shunk_t zero_prefix;
	struct ro_hunk *message[2];
	chunk_t nonce;
	chunk_t ia1;
	chunk_t ia2;
	struct crypt_mac idhash;
	v2_auth_signature_cb *cb;
	struct secret_pubkey_stuff *pks;
	const struct hash_desc *hasher;
	const struct pubkey_signer *signer;
	struct {
		size_t len;
		uint8_t ptr[sizeof(msgid_t)];
	} intermediate_wire_id;
	/* out */
	struct hash_signature signature;
};

static void v2_auth_signature_cleanup(struct ikev2_task **task, struct logger *logger)
{
	for (unsigned m = 0; m < elemsof((*task)->message); m++) {
		ro_hunk_delref(&(*task)->message[m], logger);
	}
	free_chunk_content(&(*task)->nonce);
	free_chunk_content(&(*task)->ia1);
	free_chunk_content(&(*task)->ia2);
	secret_pubkey_stuff_delref(&(*task)->pks, HERE);
	pfreeany(*task);
}

static void pack_task(struct ike_sa *ike,
		      const struct crypt_mac *idhash,
		      enum perspective from_the_perspective_of,
		      struct ikev2_task *task)
{
	enum sa_role role =
		(from_the_perspective_of == LOCAL_PERSPECTIVE ? ike->sa.st_sa_role :
		 ike->sa.st_sa_role == SA_INITIATOR ? SA_RESPONDER :
		 ike->sa.st_sa_role == SA_RESPONDER ? SA_INITIATOR :
		 0);

	struct v2AUTH_transcript transcript;
	extract_v2AUTH_transcript(ike, from_the_perspective_of, &transcript);

	chunk_t nonce = (role == SA_INITIATOR ? ike->sa.st_nr :
			 role == SA_RESPONDER ? ike->sa.st_ni :
			 empty_chunk);
	/*
	 * RFC 9242 3.3.2: both Initiator and Responder signed octets
	 * use IntAuth_iN | IntAuth_rN, independent of who is signing.
	 */
	chunk_t ia1 = ike->sa.st_v2_ike_intermediate.initiator;
	chunk_t ia2 = ike->sa.st_v2_ike_intermediate.responder;

	task->zero_prefix = transcript.zero_prefix;
	for (unsigned m = 0; m < elemsof(task->message); m++) {
		task->message[m] =
			ro_hunk_addref(transcript.message[m], ike->sa.logger);
	}
	/* on initiator, we need to hash responders nonce */
	task->nonce = clone_hunk_as_chunk(&nonce, "nonce");
	task->idhash = (*idhash);
	task->ia1 = clone_hunk_as_chunk(&ia1, "ia1");
	task->ia2 = clone_hunk_as_chunk(&ia2, "ia2");
	if (ike->sa.st_v2_ike_intermediate.id != 0) {
		/*
		 * The first IKE_AUTH exchange's ID (which is
		 * presumably immediately after the last
		 * IKE_INTERMEDIATE exchange).
		 */
		task->intermediate_wire_id.len = sizeof(task->intermediate_wire_id.ptr/*array*/);
		hton_thing(ike->sa.st_v2_ike_intermediate.id + 1, task->intermediate_wire_id.ptr/*array*/);
	}
}

bool submit_local_v2AUTH_signature(struct ike_sa *ike,
				   struct msg_digest *md,
				   const struct crypt_mac *idhash,
				   v2_auth_signature_cb *cb,
				   where_t where)
{
	const struct connection *c = ike->sa.st_connection;

	const struct hash_desc *hasher = ike->sa.st_v2_local_auth.pubkey.hash;
	const struct pubkey_signer *signer = ike->sa.st_v2_local_auth.pubkey.signer;
	enum perspective from_the_perspective_of = LOCAL_PERSPECTIVE;

	struct ikev2_task task = {
		.cb = cb,
		.hasher = hasher,
		.signer = signer,
		.signature = {0},
	};

	if (signer != NULL) {
		struct secret_pubkey_stuff *pks =
			get_local_private_key(c, signer->type,
					      ike->sa.logger);
		if (pks == NULL) {
			/* failure: no key to use */
			return false;
		}
		task.pks = secret_pubkey_stuff_addref(pks, HERE);
	}

	pack_task(ike, idhash, from_the_perspective_of, &task);

	submit_ikev2_task(ike, md,
			  clone_thing(task, "auth signature task"),
			  v2_auth_signature_helper,
			  v2_auth_signature_completed,
			  v2_auth_signature_cleanup,
			  where);
	return true;
}

static stf_status v2_auth_signature_helper(struct ikev2_task *task,
					   struct msg_digest *md UNUSED,
					   struct logger *logger)
{
	logtime_t start = logtime_start(logger);

	if (task->signer == NULL) {
		task->signature.len = task->idhash.len;
		PASSERT(logger, sizeof(task->signature.ptr) >= sizeof(task->idhash.ptr));
		memcpy_hunk(task->signature.ptr, task->idhash, task->idhash.len);
		return STF_OK;
	}

	const struct hash_hunk octets[] = {
		/* optional zero prefix and second packet, len can be 0 */
		{ "zero prefix", HUNK_REF(&task->zero_prefix), },
		{ "first packet", HUNK_REF(task->message[0]), },
		{ "second packet", HUNK_REF(task->message[1]), },
		{ "nonce", HUNK_REF(&task->nonce), },
		{ "idhash", HUNK_REF(&task->idhash), },
		/* optional intermediate, len can be 0 */
		{ "ia1", HUNK_REF(&task->ia1), },
		{ "ia2", HUNK_REF(&task->ia2), },
		{ "Intermediate ID + 1", HUNK_REF(&task->intermediate_wire_id), },
	};

	const struct hash_hunks hunks = {
		ARRAY_PTR(octets),
	};

	if (task->signer->sign_message != NULL) {
		task->signature = task->signer->sign_message(task->signer,
							     task->pks,
							     &hunks,logger);
	} else {
		struct crypt_mac hash_to_sign = crypt_hash_hunks("hash-to-sign",
								 task->hasher,
								 &hunks, logger);
		task->signature = pubkey_sign_hash(task->signer,
						   task->pks,
						   &hash_to_sign,
						   task->hasher,
						   logger);
	}
	logtime_stop(&start, "%s()", __func__);
	return STF_OK;
}

static stf_status v2_auth_signature_completed(struct ike_sa *ike,
					      struct msg_digest *md,
					      struct ikev2_task *task)
{
	return task->cb(ike, md, &task->signature);
}

