static err_t ECP_pubkey_content_to_ipseckey(const struct pubkey_content *pkc,
					    chunk_t *ipseckey,
					    enum ipseckey_algorithm_type *ipseckey_algorithm)
{
	const struct pubkey_type *type = pkc->type;
	const SECKEYECPublicKey *ec = &pkc->public_key->u.ec;
	if (type->nss.ecp.includes_ec_point_form_uncompressed) {
		*ipseckey = clone_bytes_as_chunk(ec->publicValue.data + 1, ec->publicValue.len - 1, "EC POINTS (even)");
	} else {
		*ipseckey = clone_bytes_as_chunk(ec->publicValue.data, ec->publicValue.len, "EC POINTS (even)");
	}
	*ipseckey_algorithm = type->ipseckey_algorithm;
	return NULL;
}

static void ECP_free_pubkey_content(struct pubkey_content *pkc,
				    const struct logger *logger)
{
	ldbg_delref(logger, pkc->public_key);
	SECKEY_DestroyPublicKey(pkc->public_key);
	pkc->public_key = NULL;
}

static err_t ECP_extract_pubkey_content_from_SECKEYPublicKey(struct pubkey_content *pkc,
							     SECKEYPublicKey *seckey_public,
							     SECItem *ckaid_nss,
							     const struct logger *logger)
{
	PEXPECT(logger, (pkc->type == &pubkey_type_ecdsa ||
			 pkc->type == &pubkey_type_eddsa));
	pkc->public_key = SECKEY_CopyPublicKey(seckey_public);
	ldbg_newref(logger, pkc->public_key);
	pkc->ckaid = ckaid_from_secitem(ckaid_nss);
	/* keyid; make this up */
	err_t e = keyblob_to_keyid(pkc->ckaid.ptr, pkc->ckaid.len, &pkc->keyid);
	passert(e == NULL);

	if (LDBGP(DBG_BASE, logger)) {
		ckaid_buf cb;
		LDBG_log(logger, "%s keyid *%s", pkc->type->name, str_keyid(pkc->keyid));
		LDBG_log(logger, "%s keyid *%s", pkc->type->name, str_ckaid(&pkc->ckaid, &cb));
	}

	/*
	 * The only unsafe (according to FIPS) curve is p192, and NSS
	 * does not implement this, so there is no ECDSA curve that
	 * libreswan needs to disallow for security reasons
	 */
	return NULL;
}

static bool ECP_pubkey_same(const struct pubkey_content *lhs,
			      const struct pubkey_content *rhs,
			      const struct logger *logger)
{
	/*
	 * The "adjusted" length of modulus n in octets:
	 * [RSA_MIN_OCTETS, RSA_MAX_OCTETS].
	 *
	 * According to form_keyid() this is the modulus length less
	 * any leading byte added by DER encoding.
	 *
	 * The adjusted length is used in sign_hash() as the signature
	 * length - wouldn't PK11_SignatureLen be better?
	 *
	 * The adjusted length is used in same_RSA_public_key() as
	 * part of comparing two keys - but wouldn't that be
	 * redundant?  The direct n==n test would pick up the
	 * difference.
	 */
	bool e = SECITEM_ItemsAreEqual(&lhs->public_key->u.ec.publicValue,
				       &rhs->public_key->u.ec.publicValue);
	if (LDBGP(DBG_CRYPT, logger)) {
		LDBG_log(logger, "e did %smatch", e ? "" : "NOT ");
	}

	return lhs == rhs || e;

