{
	PEXPECT(logger, (pkc->type == &pubkey_type_ecdsa ||
			 pkc->type == &pubkey_type_eddsa));

	/*
	 * Look for an EC curve with the same length as
	 * ipseckey.
	 *
	 * Raw EC pubkeys contain the EC point (or points).
	 */

	const struct ke_desc *kem = NULL;
	shunk_t raw = null_shunk;
	for (const struct ke_desc **e = kems; (*e) != NULL; e++) {
		kem = (*e);

		ldbg(logger, "pkc=%s kem=%s pubkey=%p.%zu expected=%zu uncompressed=%s",
		     pkc->type->name, kem->common.fqn,
		     ipseckey.ptr, ipseckey.len, kem->bytes,
		     bool_str(pkc->type->nss.ecp.includes_ec_point_form_uncompressed));

		/*
		 * A simple match, the buffer contains just the key.
		 */
		if (ipseckey.len == kem->bytes) {
			raw = ipseckey;
			break;
		}

		PEXPECT(logger, (pkc->type->nss.ecp.includes_ec_point_form_uncompressed ==
				 kem->nss.ecp.includes_ec_point_form_uncompressed));

		/*
		 * The raw IPSECKEY, which could come from the
		 * internet or a config file, can include the
		 * EC_POINT_FORM_UNCOMPRESSED prefix.
		 *
		 * Allow for and strip that off when necessary.
		 */
		const uint8_t *const ipseckey_ptr = ipseckey.ptr;
		if (pkc->type->nss.ecp.includes_ec_point_form_uncompressed &&
		    ipseckey.len == (*e)->bytes + 1 &&
		    ipseckey_ptr[0] == EC_POINT_FORM_UNCOMPRESSED) {
			/* ignore prefix */
			raw = shunk_slice(ipseckey, 1, ipseckey.len);
			break;
		}
	}

	if (raw.len == 0) {
		return diag("unrecognized %s Public Key with length %zu",
			    pkc->type->name, ipseckey.len);
	}

	passert(raw.ptr != NULL && raw.len > 0);

	/*
	 * Allocate the public key, giving it its own NSS arena.
	 *
	 * Since the arena contains everything allocated to the
	 * seckey, error recovery just requires freeing that.
	 */

	PRArenaPool *arena = PORT_NewArena(DER_DEFAULT_CHUNKSIZE);
	if (arena == NULL) {
		return diag_nss_error("allocating %s arena", pkc->type->name);
	}

	SECKEYPublicKey *seckey = PORT_ArenaZNew(arena, SECKEYPublicKey);
	if (seckey == NULL) {
		diag_t d = diag_nss_error("allocating %s SECKEYPublicKey",
					  pkc->type->name);
		PORT_FreeArena(arena, /*zero?*/PR_TRUE);
		return d;
	}

	seckey->arena = arena;
	seckey->keyType = key_type;
	seckey->pkcs11Slot = NULL;
	seckey->pkcs11ID = CK_INVALID_HANDLE;
	SECKEYECPublicKey *ec = &seckey->u.ec;

	/*
	 * Copy the RAW EC point(s) into the arena, adding them to the
	 * public key.
	 */

	if (kem->nss.ecp.includes_ec_point_form_uncompressed) {
		if (SECITEM_AllocItem(arena, &ec->publicValue, raw.len + 1) == NULL) {
	static const struct ke_desc *kem[] = {
		&ike_alg_ke_secp256r1,
		&ike_alg_ke_secp384r1,
		&ike_alg_ke_secp521r1,
		NULL,
	};
	return  ECP_extract_pubkey_content_from_ipseckey(ipseckey, pkc, logger, kem, ecKey);
}

static diag_t EDDSA_extract_pubkey_content_from_ipseckey(shunk_t ipseckey,
							 struct pubkey_content *pkc,
							 const struct logger *logger)
{
#ifdef USE_EDDSA
	static const struct ke_desc *kem[] = {
		&ike_alg_ke_ed25519,
		NULL,
	};
	return  ECP_extract_pubkey_content_from_ipseckey(ipseckey, pkc, logger, kem, edKey);
#else
	return diag("EDDSA not supported (%p, %p, %p)", ipseckey.ptr, pkc, logger);
#endif
}

static err_t ECP_pubkey_content_to_ipseckey(const struct pubkey_content *pkc,
					    chunk_t *ipseckey,
					    enum ipseckey_algorithm_type *ipseckey_algorithm)
{
	const struct pubkey_type *type = pkc->type;
	const SECKEYECPublicKey *ec = &pkc->public_key->u.ec;
	if (type->nss.ecp.includes_ec_point_form_uncompressed) {
		*ipseckey = clone_bytes_as_chunk(ec->publicValue.data + 1, ec->publicValue.len - 1, "EC POINTS (even)");
	} else {
		*ipseckey = clone_bytes_as_chunk(ec->publicValue.data, ec->publicValue.len, "EC POINTS (even)");
	}
	*ipseckey_algorithm = type->ipseckey_algorithm;
	return NULL;
}

static void ECP_free_pubkey_content(struct pubkey_content *pkc,
				    const struct logger *logger)
{
	ldbg_delref(logger, pkc->public_key);
	SECKEY_DestroyPublicKey(pkc->public_key);
	pkc->public_key = NULL;
}

static err_t ECP_extract_pubkey_content_from_SECKEYPublicKey(struct pubkey_content *pkc,
							     SECKEYPublicKey *seckey_public,
							     SECItem *ckaid_nss,
							     const struct logger *logger)
{
	PEXPECT(logger, (pkc->type == &pubkey_type_ecdsa ||
			 pkc->type == &pubkey_type_eddsa));
	pkc->public_key = SECKEY_CopyPublicKey(seckey_public);
	ldbg_newref(logger, pkc->public_key);
	pkc->ckaid = ckaid_from_secitem(ckaid_nss);
	/* keyid; make this up */
	err_t e = keyblob_to_keyid(pkc->ckaid.ptr, pkc->ckaid.len, &pkc->keyid);
	passert(e == NULL);

	if (LDBGP(DBG_BASE, logger)) {
		ckaid_buf cb;
		LDBG_log(logger, "%s keyid *%s", pkc->type->name, str_keyid(pkc->keyid));
		LDBG_log(logger, "%s keyid *%s", pkc->type->name, str_ckaid(&pkc->ckaid, &cb));
	}

	/*
	 * The only unsafe (according to FIPS) curve is p192, and NSS
	 * does not implement this, so there is no ECDSA curve that
	 * libreswan needs to disallow for security reasons
	 */
	return NULL;
}

static bool ECP_pubkey_same(const struct pubkey_content *lhs,
			      const struct pubkey_content *rhs,
			      const struct logger *logger)
{
	/*
	 * The "adjusted" length of modulus n in octets:
	 * [RSA_MIN_OCTETS, RSA_MAX_OCTETS].
	 *
	 * According to form_keyid() this is the modulus length less
	 * any leading byte added by DER encoding.
	 *
	 * The adjusted length is used in sign_hash() as the signature
	 * length - wouldn't PK11_SignatureLen be better?
	 *
	 * The adjusted length is used in same_RSA_public_key() as
	 * part of comparing two keys - but wouldn't that be
	 * redundant?  The direct n==n test would pick up the
	 * difference.
	 */
	bool e = SECITEM_ItemsAreEqual(&lhs->public_key->u.ec.publicValue,
				       &rhs->public_key->u.ec.publicValue);
	if (LDBGP(DBG_CRYPT, logger)) {
		LDBG_log(logger, "e did %smatch", e ? "" : "NOT ");
	}

	return lhs == rhs || e;

