+/*
+ * ML-DSA IKEv2 authentication signer
+ *
+ * FIPS 204 and draft-ietf-ipsecme-ikev2-pqc-auth.
+ */
+
+#ifdef USE_MLDSA
+
+#include <pk11pub.h>
