				}
		: authby_has_any(authby, (struct authby) {
				AUTHBY_RSASSA_PKCS1_V1_5,
			}) ? (struct authby) {
			AUTHBY_RSASSA_PKCS1_V1_5,
				}
		: authby_has(authby, AUTH_PSK) ? (struct authby) {
			AUTHBY_PSK,
				}
